<?php
require_once __DIR__.'/includes/functions.php';require_role(['admin','librarian']);$pageTitle='Issue & return books';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='issue'){$userId=(int)($_POST['user_id']??0);$bookId=(int)($_POST['book_id']??0);$due=$_POST['due_date']??'';$dueDate=DateTime::createFromFormat('Y-m-d',$due);$today=date('Y-m-d');
  if(!$userId||!$bookId||!$dueDate||$due<$today)$error='Select a student, a book, and a due date today or later.';
  else{try{$pdo=db();$pdo->beginTransaction();$b=$pdo->prepare('SELECT id,available_quantity FROM books WHERE id=? AND is_active=1 FOR UPDATE');$b->execute([$bookId]);$book=$b->fetch();$u=$pdo->prepare("SELECT id FROM users WHERE id=? AND role='student' AND status='active'");$u->execute([$userId]);$student=$u->fetch();$active=$pdo->prepare("SELECT COUNT(*) FROM issues WHERE user_id=? AND status='issued'");$active->execute([$userId]);if(!$student||!$book)throw new RuntimeException('Choose a valid active student and book.');if((int)$active->fetchColumn()>=5)throw new RuntimeException('This student already has five active loans.');if((int)$book['available_quantity']<1)throw new RuntimeException('No copies are currently available.');$ins=$pdo->prepare("INSERT INTO issues(user_id,book_id,issued_by,issue_date,due_date,status) VALUES(?,?,?,?,?,'issued')");$ins->execute([$userId,$bookId,current_user()['id'],$today,$due]);$upd=$pdo->prepare('UPDATE books SET available_quantity=available_quantity-1,times_issued=times_issued+1 WHERE id=?');$upd->execute([$bookId]);$pdo->commit();flash('success','Book issued successfully.');redirect('/loans.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Unable to issue this book. Check that the ISBN or transaction is valid.';}}
 }elseif($action==='return'){$issueId=(int)($_POST['issue_id']??0);try{$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare("SELECT * FROM issues WHERE id=? AND status='issued' FOR UPDATE");$s->execute([$issueId]);$loan=$s->fetch();if(!$loan)throw new RuntimeException('This loan is already returned or does not exist.');$returned=date('Y-m-d');$fine=fine_for($loan['due_date'],$returned);$pdo->prepare("UPDATE issues SET status='returned',return_date=? WHERE id=?")->execute([$returned,$issueId]);$pdo->prepare('UPDATE books SET available_quantity=available_quantity+1 WHERE id=?')->execute([$loan['book_id']]);if($fine>0){$check=$pdo->prepare('SELECT id FROM fines WHERE issue_id=?');$check->execute([$issueId]);if(!$check->fetch())$pdo->prepare('INSERT INTO fines(issue_id,user_id,amount,paid_amount) VALUES(?,?,?,0)')->execute([$issueId,$loan['user_id'],$fine]);}$pdo->commit();flash('success',$fine>0?'Book returned. Overdue fine recorded: '.money($fine):'Book returned successfully. No fine due.');redirect('/loans.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Unable to complete the return.';}}
}
$students=db()->query("SELECT id,name,email,student_no FROM users WHERE role='student' AND status='active' ORDER BY name")->fetchAll();$books=db()->query('SELECT id,title,author,available_quantity FROM books WHERE is_active=1 AND available_quantity>0 ORDER BY title')->fetchAll();$loans=db()->query("SELECT i.*,u.name AS student_name,u.email,b.title,b.author FROM issues i JOIN users u ON u.id=i.user_id JOIN books b ON b.id=i.book_id WHERE i.status='issued' ORDER BY (i.due_date<CURDATE()) DESC,i.due_date ASC")->fetchAll();
require __DIR__.'/includes/header.php';
?>
<div class="mb-4"><p class="text-primary small text-uppercase fw-bold mb-1">Circulation desk</p><h1 class="page-title mb-1">Issue & return books</h1><p class="muted mb-0">Loan records update inventory automatically. Overdue fine: ₹5 per day.</p></div><?php if($error): ?><div class="alert alert-danger"><?=e($error)?></div><?php endif; ?>
<div class="surface p-3 p-md-4 mb-4"><h2 class="h5 fw-bold mb-3">Issue a book</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="issue"><div class="row g-3"><div class="col-md-5"><label class="form-label">Student</label><select class="form-select" name="user_id" required><option value="">Select student</option><?php foreach($students as $s): ?><option value="<?=(int)$s['id']?>"><?=e($s['name'])?> — <?=e($s['student_no']?:$s['email'])?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Book</label><select class="form-select" name="book_id" required><option value="">Select available book</option><?php foreach($books as $b): ?><option value="<?=(int)$b['id']?>"><?=e($b['title'])?> (<?= (int)$b['available_quantity']?> available)</option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Due date</label><input class="form-control" type="date" name="due_date" min="<?=date('Y-m-d')?>" value="<?=date('Y-m-d',strtotime('+14 days'))?>" required></div><div class="col-12"><button class="btn btn-primary" type="submit"><i class="bi bi-journal-arrow-up me-1"></i> Issue book</button></div></div></form></div>
<div class="d-flex justify-content-between align-items-center gap-3 mb-3"><h2 class="h5 fw-bold mb-0">Active loans <span class="muted">(<?=count($loans)?>)</span></h2><input class="form-control" style="max-width:260px" placeholder="Search loans..." data-search-target="#loanRows"></div><div class="table-wrap"><table class="table"><thead><tr><th>Student</th><th>Book</th><th>Issued</th><th>Due date</th><th>Fine today</th><th>Action</th></tr></thead><tbody id="loanRows"><?php foreach($loans as $l): $late=$l['due_date']<date('Y-m-d');$fine=fine_for($l['due_date']); ?><tr data-searchable><td><strong><?=e($l['student_name'])?></strong><div class="small muted"><?=e($l['email'])?></div></td><td><?=e($l['title'])?><div class="small muted"><?=e($l['author'])?></div></td><td><?=e($l['issue_date'])?></td><td><span class="<?=$late?'badge-soft badge-unavailable':'badge-soft badge-available'?>"><?=e($l['due_date'])?></span></td><td><?=$late?money($fine):'—'?></td><td><form method="post" onsubmit="return confirm('Confirm that this book has been returned?')"><?=csrf_field()?><input type="hidden" name="action" value="return"><input type="hidden" name="issue_id" value="<?=(int)$l['id']?>"><button class="btn btn-sm btn-primary" type="submit">Return book</button></form></td></tr><?php endforeach; ?></tbody></table><?php if(!$loans): ?><div class="empty-state">There are no active loans.</div><?php endif; ?></div>
<?php require __DIR__.'/includes/footer.php'; ?>
